import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { Hosts } from "hosts-sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new Hosts({ baseURL: server.url, client: { clientId: 'test-client', clientSecret: 'test-secret', tokenURL: `${server.url}/oauth/token` }, maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("Client: sent by items.all", async () => {
  await client.items.all()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, 'Bearer mock-token')
  assert.ok(server.requests.some((q) => q.route === 'token'), 'the token was requested of the mock')
})
